const items = $input.all();

const output = items.map(item => {
  const user = item.json?.user?.result;
  return {
    json: {
      screenName: user?.legacy?.screen_name,
      restId: user?.rest_id,
      followersCount: user?.legacy?.followers_count,
      description: user?.legacy?.description
    }
  };
});

return output; // Set outputAsSingleArray to true if you want a single flattened array

// Set outputAsSingleArray to false for separate arrays
const outputAsSingleArray = true;

// Safely get and decode all searchTerms
const searchTerms = $items('Convert Terms').map(i => (i.json?.searchTerm ?? '').replace(/%20/g, ' '));

const results = $input.all().flatMap((item, index) => {
  const searchTerm = searchTerms[index] ?? '';

  const entries = item.json?.entries?.flatMap(e => e?.entries || []) || [];

  return entries.map(entry => {
    const tweet = entry?.content?.itemContent?.tweet_results?.result;
    const legacy = tweet?.legacy;

    if (!legacy) return null;

    const noteText = tweet?.note_tweet?.note_tweet_results?.result?.text;
    const fullText = legacy?.full_text;

    return {
      text: noteText ?? fullText ?? null,
      created_at: legacy?.created_at ?? null,
      conversation_id_str: legacy?.conversation_id_str ?? null,
      favorite_count: legacy?.favorite_count ?? null,
      view_count: tweet?.views?.count ?? null,
      search_term: searchTerm,
    };
  }).filter(e => e !== null);
});

return outputAsSingleArray ? results : results.map(r => [r]);

