// Function to parse a date string safely
function parseDate(dateStr) {
  const date = new Date(dateStr);
  return isNaN(date.getTime()) ? null : date;
}

// Function to remove all URLs from a string
function stripUrls(text) {
  return typeof text === 'string'
    ? text.replace(/https?:\/\/\S+/gi, '').trim()
    : '';
}

// Process all input items
const items = $input.all();

let mostRecentItem = null;
let mostRecentDate = null;

items.forEach(item => {
  const dateStr = item.json["Time Posted"];
  const parsedDate = parseDate(dateStr);

  if (parsedDate && (!mostRecentDate || parsedDate > mostRecentDate)) {
    mostRecentDate = parsedDate;
    mostRecentItem = item;
  }
});

if (!mostRecentItem) return [];

// Strip URLs from the "Tweet" field
const cleanedTweet = stripUrls(mostRecentItem.json.Tweet);

// Return modified item with cleaned tweet
return [{
  json: {
    ...mostRecentItem.json,
    Tweet: cleanedTweet
  }
}];

