const checkDuplicates = $('Check Duplicates').all();

return $input.all().filter(item => {
  const createdAt = item.json?.created_at;
  const text = item.json?.text;
  const conversationId = item.json?.conversation_id_str;

  if (!createdAt || typeof text !== 'string' || !conversationId) return false;

  // Exclude retweets and tweets with t.co links
  if (text.includes('RT @') || text.includes('https://t.co')) return false;

  const createdDate = new Date(createdAt);
  const now = new Date();
  const twentyFourHoursAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

  if (createdDate <= twentyFourHoursAgo || createdDate > now) return false;

  // Check duplicates and status
  const isDuplicateAndDone = checkDuplicates.some(dup => {
    return dup.json?.["Tweet ID"] === conversationId && dup.json?.Status === "Done";
  });

  return !isDuplicateAndDone;
});

return $input.all().filter(item => {
  const text = item.json?.text;

  if (typeof text !== 'string') return false;

  // Exclude retweets and any links
  if (text.includes('RT @')) return false;
  if (/https?:\/\/\S+/i.test(text)) return false;

  return true;
});
